/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')
rgb = d['rgb'].astype(np.int32)
# frame-to-frame difference magnitude
for t in [0,1,2,5,10,20,40,60,80,94,95]:
    if t==0:
        diff = np.abs(rgb[1]-rgb[0]).sum(-1)
    else:
        diff = np.abs(rgb[t]-rgb[t-1]).sum(-1)
    ys,xs = np.nonzero(diff>30)
    if len(xs):
        print(f't={t:2d} changed px={len(xs):5d} x[{xs.min()},{xs.max()}] y[{ys.min()},{ys.max()}]')
    else:
        print(f't={t:2d} no change')
\""
